"use client";
/* Sparrows, from the Piixpal shadcn registry. Options: https://piixpal.dvkk.dev/components/ */
import * as React from "react";
import { loadPiixpal, piixAttrs, type PiixProps } from "@/lib/piixpal";

export function Sparrows(props: PiixProps) {
  React.useEffect(() => { loadPiixpal("sparrows"); }, []);
  return React.createElement("piix-pal", { "pal": "sparrows", ...piixAttrs(props) });
}

export default Sparrows;
